// Validate and normalize incoming lead data
const lead = $input.first().json.body;

// Required fields check
const required = ['name', 'email', 'phone', 'source'];
const missing = required.filter(f => !lead[f]);

if (missing.length > 0) {
  return [{ json: { error: `Missing required fields: ${missing.join(', ')}`, success: false } }];
}

// Normalize data
const normalized = {
  name: lead.name.trim(),
  email: lead.email.trim().toLowerCase(),
  phone: lead.phone.replace(/[^0-9+]/g, '').trim(),
  source: lead.source.trim().toLowerCase(),
  company: (lead.company || '').trim(),
  message: (lead.message || '').trim(),
  budget: lead.budget || null,
  timestamp: new Date().toISOString(),
  lead_id: `LEAD-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`
};

// Lead scoring
let score = 0;
if (normalized.source === 'website') score += 3;
if (normalized.source === 'meta_ads' || normalized.source === 'google_ads') score += 4;
if (normalized.source === 'referral') score += 5;
if (normalized.source === 'whatsapp') score += 3;
if (normalized.budget && normalized.budget > 100000) score += 3;
if (normalized.budget && normalized.budget > 500000) score += 2;
if (normalized.message && normalized.message.length > 50) score += 2;
if (normalized.company) score += 2;

normalized.lead_score = score;
normalized.priority = score >= 8 ? 'hot' : score >= 5 ? 'warm' : 'cold';
normalized.qualification_status = 'pending';

return [{ json: normalized }];

// Generate instant WhatsApp response based on lead data
const lead = $input.first().json;

let response = '';

if (lead.priority === 'hot') {
  response = `Hi ${lead.name}! 👋\n\nThank you for your interest! A senior consultant will contact you within the next 15 minutes.\n\nYour reference: ${lead.lead_id}\n\nWe noticed you're looking for ${lead.company ? 'solutions for ' + lead.company : 'our services'}. We have some great options to discuss.\n\nTalk soon!`;
} else if (lead.priority === 'warm') {
  response = `Hi ${lead.name}! 👋\n\nThank you for reaching out! We've received your enquiry and a member of our team will be in touch within the hour.\n\nYour reference: ${lead.lead_id}\n\nIn the meantime, feel free to reply with any questions!`;
} else {
  response = `Hi ${lead.name}! 👋\n\nThanks for your interest! We've received your enquiry and will get back to you shortly.\n\nYour reference: ${lead.lead_id}`;
}

return [{
  json: {
    ...lead,
    whatsapp_response: response,
    response_type: 'instant_whatsapp'
  }
}];

// Generate email response
const lead = $input.first().json;

const emailSubject = `Thank you for your enquiry - ${lead.lead_id}`;

const emailBody = `
<!DOCTYPE html>
<html>
<body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
<div style="background: #1a1a2e; padding: 30px; text-align: center;">
  <h1 style="color: #c9a84c; margin: 0;">JULES LUXURY</h1>
  <p style="color: #fff; margin: 5px 0 0 0;">CARS & LOGISTICS</p>
</div>
<div style="padding: 30px; background: #f9f9f9;">
  <h2 style="color: #1a1a2e;">Thank you, ${lead.name}!</h2>
  <p>We've received your enquiry and our team is reviewing it now.</p>
  <p><strong>Your Reference:</strong> ${lead.lead_id}</p>
  ${lead.company ? `<p><strong>Company:</strong> ${lead.company}</p>` : ''}
  <p>A member of our team will contact you shortly to discuss how we can help.</p>
  <hr style="border: 1px solid #ddd;">
  <p style="color: #666; font-size: 12px;">Jules Luxury Cars & Logistics | Lagos, Nigeria</p>
  <p style="color: #666; font-size: 12px;">+234 810 470 4552 | support@julesluxurytransports.com</p>
</div>
</body>
</html>
`;

return [{
  json: {
    ...lead,
    email_subject: emailSubject,
    email_body: emailBody,
    email_to: lead.email,
    email_from: 'noreply@julesluxurytransports.com'
  }
}];

// Generate CRM log entry
const lead = $input.first().json;

const crmEntry = {
  lead_id: lead.lead_id,
  name: lead.name,
  email: lead.email,
  phone: lead.phone,
  source: lead.source,
  company: lead.company,
  message: lead.message,
  budget: lead.budget,
  lead_score: lead.lead_score,
  priority: lead.priority,
  qualification_status: 'new',
  assigned_to: null,
  notes: [],
  timeline: [
    {
      action: 'lead_captured',
      timestamp: lead.timestamp,
      details: `Lead captured from ${lead.source}`
    },
    {
      action: 'instant_response_sent',
      timestamp: lead.timestamp,
      details: 'WhatsApp and email responses sent'
    }
  ],
  created_at: lead.timestamp,
  updated_at: lead.timestamp
};

return [{ json: crmEntry }];

// Generate salesperson notification
const lead = $input.first().json;

let notification = '';

if (lead.priority === 'hot') {
  notification = `🔥 HOT LEAD ALERT

Name: ${lead.name}
Company: ${lead.company || 'N/A'}
Source: ${lead.source}
Score: ${lead.lead_score}/15
Phone: ${lead.phone}

Message: ${lead.message || 'No message'}

⚡ Contact within 15 minutes!`;
} else if (lead.priority === 'warm') {
  notification = `📬 New Lead

Name: ${lead.name}
Company: ${lead.company || 'N/A'}
Source: ${lead.source}
Score: ${lead.lead_score}/15
Phone: ${lead.phone}

⏰ Contact within 1 hour.`;
} else {
  notification = `📋 New Lead

Name: ${lead.name}
Source: ${lead.source}
Score: ${lead.lead_score}/15

Follow up within 24 hours.`;
}

return [{
  json: {
    ...lead,
    salesperson_notification: notification,
    notification_priority: lead.priority === 'hot' ? 'urgent' : 'normal'
  }
}];

// Final summary - all actions completed
const lead = $input.first().json;

return [{
  json: {
    status: 'completed',
    lead_id: lead.lead_id,
    name: lead.name,
    priority: lead.priority,
    lead_score: lead.lead_score,
    actions_taken: [
      'Lead validated and scored',
      'WhatsApp response generated',
      'Email response generated',
      'CRM entry created',
      'Salesperson notified'
    ],
    timestamp: new Date().toISOString()
  }
}];
